    "md.llama-32-3b.selfHost": "発行元のOnePlus 12 BF16例: 7,419MB RSS。普遍的な最小値ではありません。",
    "md.llama-32-3b.pros.0": "フルプレシジョンファミリーで128Kコンテキストを持つ3.21Bテキストモデル。",
    "md.llama-32-3b.pros.1": "MacBook Airで30トークン/秒以上",
    "md.llama-32-3b.pros.2": "巨大なファインチューンのエコシステム",
    "md.llama-32-3b.cons.0": "カスタムライセンスと許容される使用条件が適用されます。これには帰属表示と大規模プラットフォームライセンス条件が含まれます。",
    "md.llama-32-3b.cons.1": "コミュニティライセンス、OSI未承認",
    "md.llama-32-1b.selfHost": "発行元のOnePlus 12 BF16例: 3,185MB RSS。量子化デプロイメントは異なります。",
    "md.llama-32-1b.pros.0": "1.23Bテキストモデル。フルプレシジョンコンテキストは128K。リストされている量子化テキストモデルは8Kを使用します。",
    "md.llama-32-1b.pros.1": "入り口として最適：誰でもこれでローカルAIを試せる",
    "md.llama-32-1b.cons.0": "カスタムライセンス、許容される使用条件、および帰属表示の条件が適用されます。ベースチェックポイントまたは指示チューニング済みチェックポイントが必要かどうかを確認してください。",
