    "md.muse-glimmer-30b.cons.0": "カードはK-Quant-17GBバリアントに24GB VRAMをターゲットとしています。モデルは18歳未満を対象としていないと記載されています。",
    "md.muse-glimmer-30b.cons.1": "完全なローカルスタックには24〜32GBのメモリが必要",
