    "k1198": "[87] TIME、「独占：Anthropic、主要な安全誓約を撤回」、2026年2月24日：<a href=\"https://time.com/7380854/exclusive-anthropic-drops-flagship-safety-pledge/\" target=\"_blank\" rel=\"noopener noreferrer\">TIME報道</a>。",
    "k1199": "[88] Anthropic、「責任あるスケーリングポリシー バージョン3.0」、2026年2月 — <a href=\"https://www.anthropic.com/news/responsible-scaling-policy-v3\" target=\"_blank\" rel=\"noopener noreferrer\">anthropic.com</a>",
    "k1200": "[89] OpenAI、「当社の組織構造」、2025年10月の再資本化後に更新 — <a href=\"https://openai.com/our-structure/\" target=\"_blank\" rel=\"noopener noreferrer\">openai.com</a>",
    "k1201": "[90] The Conversation via Business Standard、「OpenAI、新組織構造がAIの忠誠心を試す中、ミッションから『安全に』を削除」、2026年2月15日：<a href=\"https://www.business-standard.com/technology/tech-news/openai-drops-safely-from-mission-as-new-structure-tests-ai-s-loyalties-126021500074_1.html\" target=\"_blank\" rel=\"noopener noreferrer\">ミッション文言に関する解説</a>。株式保有率から管理権への推論は使用すべきではありません。OpenAIのガバナンス権[89]を参照してください。",
    "k1202": "[91] Infosecurity Magazine、「OpenAI、Microsoft、Google、AnthropicがAI規制のための組織を設立」、2023年7月 — <a href=\"https://www.infosecurity-magazine.com/news/openai-microsoft-google-anthropic/\" target=\"_blank\" rel=\"noopener noreferrer\">infosecurity-magazine.com</a>",
    "k1203": "[92] The Verge、「AIスーパーインテリジェンスの減速」、2026年10月更新のローリングカバレッジ：<a href=\"https://www.theverge.com/ai-artificial-intelligence/996923/ai-safety-slow-openai-anthropic\" target=\"_blank\" rel=\"noopener noreferrer\">The Vergeカバレッジ</a>。10月9日のインシデントレポートについては、一次情報源[98]を参照してください。",
