    "a90.0bd54214257b@placeholder": "例：「EVTから月産4万台のコンシューマーオーディオデバイスを量産まで持ち込みました。DFMレビューとテストジグ仕様を所有しています。Enki Oneでも同様のことを喜んで行います。」",
