    "v94.81b12b456e2a": "1つのOpenAI互換サーフェス",
    "v94.417dafa10633": "さらに発見機能 — 公開され、バージョン管理され、意図的に退屈なもの。",
    "v94.a9c4998c6cab": "TypeScript、Python、Swift、Kotlin — それぞれ5行のクイックスタートとリファレンスアプリ付き。",
    "v94.6b79a7769172": "Claude Code、エージェント、IDEは初日からメッシュをツールとして認識します。",
    "v94.a844f9675812": "ChatGPT、Perplexity、Gemini、エージェントスタック — 1つのインストールページ、それぞれが指名されたメンバーによって最新の状態に保たれます。",
    "v94.a13d07734bed": "まずLibreChat、次に最も使用されているオープンクライアント — 薄いフォーク、活発なアップストリームPR。",
    "v94.ef7263f6b262": "公開テストスイート。合格すれば、クライアントはバッジを付けられます。レジストリには認定されたすべてのクライアントがリストされます。",
