    "a90.3a51ce88d3a1@alt": "Enkiデバイスのコンセプトレンダリング：手のひらサイズの白いセラミック製小石、丸い真鍮の電源ボタン、小さなバッテリーLED、単一のUSB-Cポート、画面なし",
    "a90.4306523a0699@alt": "手に持たれた白いセラミック製Enkiデバイスのコンセプトレンダリング。後ろのテーブルには、コンパニオンアプリを実行しているスマートフォン、スマートグラス、イヤホンが置かれている",
    "meta90.aa6a48227049@content": "EnkiデバイスはポケットサイズのローカルAIコンセプトであり、まだ製品ではありません。そのエンジニアリング目標、オープンデザイン目標、制約、およびホームメッシュでの提案される役割を探求してください。",
    "r90.cdb263af2652": "Enki — 知性は、すべての人、すべての場所に属します",
