    "home94.clientAlt@alt": "ローカルAIデバイスと共有メモリキャビネットに接続されたスマートフォンとラップトップ",
    "a90.4fd3091d6997@alt": "ラップトップ、テレビ、電話が青いメッシュラインで小さな小石デバイスに接続されている家のアイソメトリック断面図",
    "home94.registryAlt@alt": "カタログ、モデルブロック、互換性のあるハードウェアを備えたアイソメトリックモデルライブラリ",
    "a90.0f6e6ca7f859@alt": "手に持たれたEnkiデバイスと、それがサービスを提供する周囲のデバイス",
    "home94.instituteAlt@alt": "コミュニティに接続されたオープンな研究所の周りのテーブルで証拠を共有する研究者",
    "a90.bf5f03b7aca0@alt": "上から見た同心円状に立つ300人の人々、1つの席が青く光っている",
    "meta90.693be0c4fe13@content": "Enkiは、ローカルファーストAIのための未登録の公共善イニシアチブです：マニフェスト、300席の設立目標、オープンウェイトカタログ、および提案されたデバイス、クライアント、メッシュデザイン。",
    "r90.c4f0153750d9": "Enki研究所 &amp; 諮問機関 — 変化を理解し、それを導く",
    "art91.proposed": "提案された研究機関",
    "art91.evidence": "公開証拠",
    "art91.work": "仕事",
    "art91.culture": "文化",
    "art91.power": "権力",
    "art91.research": "研究",
    "art91.advisory": "諮問機関",
    "r90.200dfa43f58b": "Paul Fleuryがお客様のお問い合わせを検討し、返信いたします。<a href=\"/privacy\" target=\"_blank\" rel=\"noopener\">プライバシー通知（英語）</a>。",
    "meta90.3d77324d77e7@content": "提案されたEnki研究所と諮問機関は、AIを研究し、ローカルファーストの仮定をテストし、証拠に基づいた政策をサポートします。プログラムは現在構築中です。",
    "meta90.dd0289bfa34c@content": "Enki研究所 &amp; 諮問機関 — 変化を理解し、それを導く",
    "r90.77aa2fcc5e91": "300人に参加する — Enkiメンバーシップ",
    "svg90.9b0c3358ab88": "席 · 無料 · 各1票",
    "r90.c48fa80e177c": "<span class=\"hero-stat__value\">300</span><span class=\"hero-stat__label\">席 — 創設者であるポール・フルーリーを含む299人のメンバー。設立初年度は席に着き、その後は名誉創設者</span>",
    "r90.c700be0a77ef": "<span class=\"hero-stat__value\">$0</span><span class=\"hero-stat__label\">無料、支払いなし — 選考、サブスクリプションではありません</span>",
    "r90.edd0e5940a16": "<span class=\"hero-stat__value\">2</span><span class=\"hero-stat__label\">提案されたチェック：本人確認と面接</span>",
    "r90.f7946ef68246": "<span class=\"hero-stat__value\">1</span><span class=\"hero-stat__label\">メンバーごとの平等な投票権、承認された規則の下で</span>",
    "meta90.4c1901ec6ce1@content": "Enkiの設立イニシアチブに応募してください：目標300名の個人会員、会員費なし、提案されている平等な投票と貢献ベースの審査。まだ法人化されていません。",
    "r90.2f81576d7881": "Enkiマニフェスト — 知能の状態に関する書簡",
    "r90.2aef22c24d38": "知能の状態に関する書簡。",
    "r90.25b5fc75c801": "10の記事と後書き：ローカルファーストの議論、そのトレードオフ、および98の参考文献と背景資料。",
    "r90.beebeec0e3a9": "書簡を読む",
    "r90.ed7e177720d3": "なぜ「Enki」なのか？",
    "audit.policyDial": "この分割は政策上の選択であり、ワークロードの99％がすでにローカル対応可能であるという主張ではありません。日常的なツールは、リモートサービスが利用できない場合でも使用可能であるべきです。最も重要な機能には、比例した監視が必要です。両方の目標には、実装、テスト、および公開アカウンタビリティが必要です。",
    "audit.ref.93": "[93] Anthropic、「Accentureとの組み込み評価に関する提携」、2026年9月18日：<a href=\"https://www.anthropic.com/news/accenture-embedded-evaluation\" target=\"_blank\" rel=\"noopener noreferrer\">www.anthropic.com</a>。",
    "audit.ref.94": "[94] CNBC、「AIの静かな安全の番人が脚光を浴びる」、2026年10月11日：<a href=\"https://www.cnbc.com/2026/10/11/ais-quiet-safety-gatekeepers-are-stepping-into-the-spotlight.html\" target=\"_blank\" rel=\"noopener noreferrer\">www.cnbc.com</a>。",
    "audit.ref.95": "[95] Open Source Initiative、「オープンソースAI定義、バージョン1.0」、2024年10月：<a href=\"https://opensource.org/ai/open-source-ai-definition\" target=\"_blank\" rel=\"noopener noreferrer\">opensource.org</a>。",
    "audit.ref.96": "[96] Model Context Protocol、「Security Best Practices」、2026-07-28ドキュメント：<a href=\"https://modelcontextprotocol.io/docs/2026-07-28/tutorials/security/security_best_practices\" target=\"_blank\" rel=\"noopener noreferrer\">modelcontextprotocol.io</a>。",
    "audit.ref.97": "[97] The Update Framework、現在の仕様、2026年10月11日アクセス：<a href=\"https://theupdateframework.github.io/specification/latest/\" target=\"_blank\" rel=\"noopener noreferrer\">theupdateframework.github.io</a>。",
    "audit.ref.98": "[98] Anthropic、「評価および内部使用における意図しないモデルの動作の調査」、2026年10月9日：<a href=\"https://www.anthropic.com/research/investigating-unintended-model-actions\" target=\"_blank\" rel=\"noopener noreferrer\">www.anthropic.com</a>。",
