    "md.sep.13.n": "リストされているパラメータは14Bから70B。量子化とランタイムを指定する必要があります。",
    "md.sep.31.t": "コンパクトチェックポイント",
    "md.sep.31.n": "リストされているパラメータは4Bから14B。メモリは重みファイル以上です。",
    "md.sep.43.t": "小型チェックポイント",
    "md.sep.43.n": "リストされているパラメータは最大4B。電話との互換性はデバイスレベルのテストが必要です。",
    "simple94.lede": "大企業から借りるだけでなく、自分で所有・管理できる、便利で日常的な人工知能の提案。",
    "simple94.sections.0.h": "あなたのAI、あなたのルール",
    "simple94.sections.0.p.0": "Enkiは、あなたが所有するデジタルツールとそれらが作成するデータを、少数の大企業から借りるだけでなく、自分で管理すべきだと考えています。目標は、日常的なAIをよりアクセスしやすく個人的なものにし、あなたのニーズと価値観に合うようにすることです。",
    "simple94.sections.0.p.1": "このアプローチはバランスを求めています。高度なAIシステムには監視が必要ですが、あなたが日常的に使用する便利なAIは、あなたが所有するハードウェアで実行されるべきです。このビジョンが、プロジェクトの他のすべての部分を形作っています。",
    "simple94.sections.1.h": "あなたのデバイスのための共通言語",
    "simple94.sections.1.p.0": "提案されているプロトコルは、別のAIモデルではなく、共通言語です。あなたの許可を得て、異なるメーカーの互換性のあるデバイスが連携できるようになります。あなたの電話は、あなたが既に所有しているより高性能なコンピュータにタスクを送信できます。",
    "simple94.sections.1.p.1": "共有ルールは、接続とモデルアップデートの出所の確認をカバーし、アプリとハードウェアが単一企業の生態系に属することなく連携できるようにします。",
    "simple94.sections.1.link": "プロトコルを見る",
    "simple94.sections.2.h": "あなたが話しかけるアプリ",
    "simple94.sections.2.p.0": "クライアントは、AIと対話するために使用するアプリまたはインターフェースです。Enkiは、それを実行するエンジンから分離することを目指しており、プロバイダーのクラウドに縛られることなくアプリを選択できるようにします。",
    "simple94.sections.2.p.1": "提案されているContext Vaultは、有用なメモリをハードウェアに保持するため、アプリを変更しても最初からやり直す必要がなくなります。各アプリへのアクセス権限はあなたが選択します。クラウドサービスを使用する場合、共有された情報はローカル環境から離れます。",
    "simple94.sections.2.link": "クライアントを探る",
    "simple94.sections.3.h": "AIモデルを選択するためのカタログ",
    "simple94.sections.3.p.0": "Registryは、AIモデルの選択を支援するための公開された開始カタログです。各モデルの機能、ライセンス、ハードウェア要件、およびクラウドまたはセルフホスティングの推定コストをリストしています。",
    "simple94.sections.3.p.1": "品質やコスト削減を保証するものではありませんが、設立された300のコミュニティが成長するにつれて改善を目指しています。これにより、ニーズに合った適切なツールを比較検討できます。",
    "simple94.sections.3.link": "レジストリを閲覧する",
    "simple94.sections.4.h": "あなたのAIのためのポータブルホーム",
    "simple94.sections.4.p.0": "Enkiデバイスは、サポートされているAIモデル自体を実行する小型でポータブルなコンピュータのコンセプトです。あなたの電話やアプリはそれに接続し、ローカルAIを家庭やオフィスを超えて拡張します。",
    "simple94.sections.4.p.1": "目標は、必須のクラウドアカウントなしでサポートされているタスクを処理することです。オープンで構築可能な設計により、さまざまなメーカーが製造できるようになります。まだ利用可能ではなく、ハードウェア、電力、維持費は依然として費用がかかります。",
    "simple94.sections.4.link": "デバイスを見る",
    "simple94.sections.5.h": "AIの影響を理解する",
    "simple94.sections.5.p.0": "Enki Instituteは、AIの現実世界への影響に関する調査結果を公開する予定の研究機関です。AIが仕事、文化、経済力にどのように変化をもたらすかを研究し、結果をオープンに共有します。",
    "simple94.sections.5.p.1": "研究所はEnki自身のアイデアをテストし、証拠に基づいた助言を提供します。その目標は、他者がテクノロジーに関する情報に基づいた意思決定を行えるよう支援することです。",
    "simple94.sections.5.link": "研究所を見る",
    "simple94.status.h": "プロジェクト状況",
    "simple94.status.p.0": "マニフェスト、プロジェクト提案、およびスターターモデルカタログは公開されています。プロトコル、クライアント、ポータブルデバイス、および研究所はまだ構築およびテストが必要です。「300」は、これらのアイデアを開発するための設立グループの目標であり、現在のメンバー数ではありません。会費はありません。",
    "simple94.back": "Enki.ngoに戻る",
    "simple94.read": "3分で読む",
    "simple94.act.h": "参加する",
